using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "CriticalTwistAchievementData", menuName = "Data/Achievements/CriticalTwistAchievementData")]
public class CriticalTwistAchievementData : AchievementData
{
	[SerializeField]
	private DiceTier safeDiceTier;

	public void CriticalTwistUnlock(int purifyAmount, GameObject source)
	{
		if (!IsUnlocked() && ReferenceSingleton<BattleHandler>.Instance.IsSourcePlayer(source) && purifyAmount >= base.AchievementVariableAmount && ReferenceSingleton<BattleHandler>.Instance.LateCurrentActionInstance is DiceInstance && (ReferenceSingleton<BattleHandler>.Instance.LateCurrentActionInstance as DiceInstance).Dice.DiceTier == safeDiceTier)
		{
			Unlock();
		}
	}
}
